TLM.f("Sancti/10-18",{"officium":"S. Lucæ Evangelistæ","rule":["ex C1a;","Gloria","Credo","Prefatio=Apostolis"],"ruleInherited":["Psalmi Dominica","Antiphonas horas","Psalm5 Vespera=116","Psalm5 Vespera3=138"],"fallback":"Commune/C1a","sections":{"Introitus":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."},{"k":"ref","la":"Ps 138:1-2"},{"k":"text","la":"Dómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Oratio":[{"k":"text","la":"Intervéniat pro nobis, quǽsumus, Dómine, sanctus tuus Lucas Evangélista: qui crucis mortificatiónem júgiter in suo córpore, pro tui nóminis honóre, portávit."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 8:16-24"},{"k":"text","la":"Fratres: Grátias ago Deo, qui dedit eandem sollicitúdinem pro vobis in corde Titi, quóniam exhortatiónem quidem suscépit: sed cum sollicítior esset, sua voluntáte proféctus est ad vos. Mísimus étiam cum illo fratrem, cujus laus est in Evangélio per omnes ecclésias: non solum autem, sed et ordinátus est ab ecclésiis comes peregrinatiónis nostræ in hanc grátiam, quæ ministrátur a nobis ad Dómini glóriam et destinátam voluntátem nostram: devitántes hoc, ne quis nos vitúperet in hac plenitúdine, quæ ministrátur a nobis. Providémus enim bona non solum coram Deo, sed étiam coram homínibus. Mísimus autem cum illis et fratrem nostrum, quem probávimus in multis sæpe sollícitum esse: nunc autem multo sollicitiórem, confidéntia multa in vos, sive pro Tito, qui est sócius meus, et in vos adjútor, sive fratres nostri, Apóstoli ecclesiárum, glória Christi. Ostensiónem ergo, quæ est caritátis vestræ, et nostræ glóriæ pro vobis, in illos osténdite in fáciem ecclesiárum."}],"Graduale":[{"k":"ref","la":"Ps 18:5; 18:2"},{"k":"text","la":"In omnem terram exívit sonus eórum: et in fines orbis terræ verba eórum."},{"k":"text","la":"Cœli enárrant glóriam Dei: et ópera mánuum ejus annúntiat firmaméntum. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Joann 15:16"},{"k":"text","la":"Ego vos elégi de mundo, ut eátis et fructum afferátis: et fructus vester máneat. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 10:1-9"},{"k":"text","la":"In illo témpore: Designávit Dóminus et álios septuagínta duos: et misit illos binos ante fáciem suam in omnem civitátem et locum, quo erat ipse ventúrus. Et dicebat illis: Messis quidem multa, operárii autem pauci. Rogáte ergo Dóminum messis, ut mittat operários in messem suam. Ite: ecce, ego mitto vos sicut agnos inter lupos. Nolíte portáre sácculum neque peram neque calceaménta; et néminem per viam salutavéritis. In quamcúmque domum intravéritis, primum dícite: Pax huic dómui: et si ibi fúerit fílius pacis, requiéscet super illum pax vestra: sin autem, ad vos revertátur. In eádem autem domo manéte, edéntes et bibéntes quæ apud illos sunt: dignus est enim operárius mercéde sua. Nolíte transíre de domo in domum. Et in quamcúmque civitátem intravéritis, et suscéperint vos, manducáte quæ apponúntur vobis: et curáte infírmos, qui in illa sunt, et dícite illis: Appropinquávit in vos regnum Dei."}],"Offertorium":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Secreta":[{"k":"text","la":"Donis cœléstibus da nobis, quǽsumus, Dómine, líbera tibi mente servíre: ut múnera quæ deférimus, interveniénte beáto Evangelísta tuo Luca, et medélam nobis operéntur et glóriam."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 19:28"},{"k":"text","la":"Vos, qui secúti estis me, sedébitis super sedes, judicántes duódecim tribus Israël."}],"Postcommunio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, quod de sancto altári tuo accépimus, précibus beáti Evangelístæ tui Lucæ, sanctíficet ánimas nostras, per quod tuti esse possímus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"62db1d5faaebcb51":{"t":"<i>Pomolimo se</i>.\nZagovarao nas, molimo, Gospodine, tvoj sveti evanđelist Luka, koji je mrtvljenje križa vazda nosio na svom tijelu na čast tvoga imena.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Zagovarao nas, molimo, GosipOdine,. sveti Tvoj evanđelista Luka,, koji .je mrtvljenje križa vazda nosiO' u svom srcu. na čast imena Tvoga,, po G. 'n.i.\" ■ . ■ : ■ ■ ■ _ ■","knRef":"Kniewald 1942, str. 740–741 (snimka 371) (OCR)"},"760a7dc9e9a0af37":{"t":"Ovim nebeskim darovima daj nam, Gospodine, da ti slobodnom dušom služimo, te nam prinosi, što ih prikazujemo, zagovorom blaženog Luke, tvoga evanđelista, isprose tvoju pomoć i slavu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ovim nebeskim darovima daj nam. Gospodine, da Ti slobodnom dušom služimo, te nam prinosi, što ih prikazujemo, zagovorom blaženog Luke, evanđeliste Tvoga, isprose i pomoć i slavu, po G. n.","knRef":"Kniewald 1942, str. 742–743 (snimka 372) (OCR)"},"ec775b23db9a9d7b":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da molitve blaženoga tvoga evanđeliste Luke isprose posvećenje naših duša po svetinjama što ih primismo sa tvoga svetog oltara da tako uzmognemo biti sigurni.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da molitve blaženoga evanđeliste Tvoga Luke ishode posvećenje naših duša ipo svetinjama, što ih primismo sa svetoga Tvoga oltara, da tako uzmognemo biti bezbjedni; po Gospodinu ...","knRef":"Kniewald 1942, str. 742–743 (snimka 372) (OCR)"},"4ce2969ae90d1d66":{"t":"Ps 138, 17, Ps 138, 1-2\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove. (Ps 138, 1-2) Gospodine, ti si me kušao i spoznao, tebi je poznat moj počinak i moje uskrsnuće.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove.","kn":"(Ps. 138, 17). Veoma častim prijatelje Tvoje, Bože, silno je utvrđeno kneževstvo njihovo. (Ps. 133, 1). Gospodine, Ti sj me kušao i spoznaoi; Tebi je poznat moj počinak i moje ustajanje. Slava Ocu . . . Veoma ...","knRef":"Kniewald 1942, str. 458–459 (snimka 230) (OCR)"},"aa790c38b8b58062":{"t":"2 Kor 8, 16-24\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo: Zahvaljujem Bogu koji je istu revnost za vas postavio u Titovo srce. Ja sam ga doista zamolio, ali jer je nastojao i sam, otputovao je svojevoljno k vama. Poslali smo s njim i brata, kojega radi evanđelja slave sve Crkve. Ali ne samo to, nego su Crkve izabrale da bude naš pratilac u ovom djelu ljubavi koje mi vršimo da slavimo Boga i posvjedočimo našu dobru volju. Tim i sebe zaštićujemo da nas ne bi tko kudio radi obilnih prinosa koje dijelimo. Brinemo se za dobro ne samo pred Gospodinom, nego i pred ljudima. S njim smo poslali i našega brata, čiju smo revnost iskusili u mnogim stvarima, a sada je on još revniji radi velikog pouzdanja koje goji prema vama; Ili radi Tita koji je moj drug. i pomoćnik među vama, ili radi braće koji su apostoli Crkava i slava Kristova. Pokažite pred Crkvom svoju ljubav radi koje se mi dičimo vama.","kn":"Čitanje poslanice bi. Pavla apostola Korinćanima (II, 8, 16-24). Braćo! Zahvaljujem Bogu, koji, je istu revnost za vas postavio u Titovo srce. Ja sam ga doista zamolio, ali jer je nastojao i sam, otputovao je svojevoljno k vama. Poslali smo s njim i brata, kojega radi evanđelja slave sve Crkve. Ali ne samo to, nego su Crkve izabrale, da bude naš pratilac o ovom djelu ljubavi, koje mi vršimo, da slavimo Boga i. posvjedočimo našu dobru volju. Tim i sebe zaštićujemo, da nas ne bi tko kudio radi obilnih prinosa, koje dijelimo. Brinemo se za dobro ne samo pred Gospodinom, nego i pred ljudima. S njim smo poslali i našega brata, čiju smo revnost često iskusili u mnogim stvarima, a sada je on još revniji radi velikoga pouzdanja, koje goji prema vama. Ili radi Tita, koji je moj drug i pomoćnik među vama, ili radi braće, koji su apostoli Crkava i slava Kristova. Pokažite pred Crkvom svoju ljubav, radi koje se mi dičimo vama.","knRef":"Kniewald 1942, str. 740–741 (snimka 371) (OCR)"},"ddb4aa05ce27dfc8":{"t":"Ps 18, 5 et 2\nPo svoj zemlji iziđe njihov glas, i do na kraj svijeta njihova nauka. Nebesa pripovijedaju slavu Božju i svod nebeski naviješta djelo njegovih ruku.\n\nIo 15, 16\n<i>Aleluja</i>, <i>aleluja</i>.\nJa sam vas izabrao od svijeta da idete i plod donesete i plod vaš da ostane. <i>Aleluja</i>.","kn":"(Ps. 18, 5). Po svoj zemlji iziđe glas njihov, i do na kraj svemira riječi njihove. Nebesa pripovijedaju slavu Božju, i djelo ruku njegovih I naviiješta svod nebeski.\n\nAleluja, aleluja. (Iv. 15, 16.) Ja vas izabrah od svijeta, da idete i plod donesete i plod vaš da ostane, aleluja.","knRef":"Kniewald 1942, str. 742–743 (snimka 372) (OCR)"},"22b5143a1c0cf786":{"t":"Lk 10, 1-9\nSlijedi sveto Evanđelje po Luki. U ono vrijeme odredi Gospodin i drugu sedamdeset i dvojicu i posla ih dva po dva pred sobom u svaki grad i mjesto kamo je sam kanio doći. I govorio im je: Žetva je velika, a radnika je malo. Zato molite gospodara žetve da pošalje radnike u svoju žetvu. Idite: Evo, ja vas šaljem kao janjce među vukove. Ne nosite ni kese ni torbe ni obuće i nikoga ne pozdravljajte na putu. U kojugod kuću uđete, kažite najprije: Mir ovoj kući! I ako tko ondje bude dostojan mira, ostat će na njemu vaš mir, ako ne bude, vratit će se k vama. Ostanite u onoj kući, jedite i pijte što imaju jer radnik zaslužuje svoju plaću. Ne prelazite iz kuće u kuću. I u kojigod grad uđete i prime vas, jedite, što postave pred vas. I liječite bolesne koji su u njemu, i kažite im: Približilo vam se kraljevstvo Božje!","kn":"t Slijedi sv. evanđelje Po Luki (10, 1-9). U ono vrijeme odredi Gospodin i drugu sedamdeset i dvojicu 1 posla ih dva po dva pred sobom u svaki gnad i mjesto, kamo je sam kanio doći. I govorio, im je: Žetva je velika, a radnika je malo. Zato molite gospodara žetve, da pošalje radnike u svoju žetvu. Idite: Evo, ja vas šaljem kao janjce među vukove. Ne nosite ni kese ni torbe ni obuće, i nikoga ne pozdravljajte na putu. U kojugod kuću uđete, kažite najprije: Mir ovoj kući! I ako tko ondje bude dostojan mira, ostat će na njemu vaš mir, ako ne bude, vratit će se k vama. Ostanite u onoj kući, jedite i pijte, što imaju, jer radnik zaslužuje svoju plaću.. Ne prelazite iz kuće u kuću. I u kojigođ grad uđete 1 prime vas, jedite, što se. donese pred vas. I liječite bolesne, koji su u njemu, i kažite im: Približilo vam se kraljevstvo Božje! .","knRef":"Kniewald 1942, str. 734–735 (snimka 368) (OCR)"},"8bade162dbdb175e":{"t":"Ps 138, 17\nNada sve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove.","kn":"(Ps. 138, 17). Veoma častim prijatelje Tvoje, Bože, silno se utvrdi kneževstvo njihovo!","knRef":"Kniewald 1942, str. 742–743 (snimka 372) (OCR)"},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"4379ab930a0e53cb":{"t":"Mt 19, 28\nVi koji ste pošli za mnom sjedit ćete na prijestoljima i suditi dvanaest plemena Izraelovih.","kn":"(Mt. 19, 28). Vi. koji ste slijedili mene, sjedit ćete na prijestolima sudeći dvanaest plemena Izraelovih,","knRef":"Kniewald 1942, str. 628–629 (snimka 315) (OCR)"}}});
